import{c as e,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"is_convertible","description":"","frontmatter":{},"headers":[{"level":1,"title":"is\\\\_convertible","slug":"is_convertible"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/C++标准库/类型特性/is_convertible.md","filePath":"api/Utils-API/C++标准库/类型特性/is_convertible.md"}'),l={name:"api/Utils-API/C++标准库/类型特性/is_convertible.md"};function i(d,a,p,r,o,c){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="is-convertible" tabindex="-1">is_convertible <a class="header-anchor" href="#is-convertible" aria-label="Permalink to &quot;is\\_convertible&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>is_convertible是定义于&lt;type_traits&gt;头文件的一个类型转换检查工具，它提供了一种在程序编译时进行类型转换检查的机制：判断两个类型之间是否可以进行隐式转换并返回结果布尔值。本接口可应用在模板元编程、函数重载决议以及静态断言等场景，用于在程序编译阶段捕获潜在的类型转换错误，避免发生运行时错误。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename From, typename To&gt;</span></span>
<span class="line"><span>struct is_convertible;</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>含义</th></tr></thead><tbody><tr><td>From</td><td>源类型，即需要进行转换的原始类型。</td></tr><tr><td>To</td><td>目标类型，即需要转换到的目标类型。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>源类型和目标类型均不支持抽象类和多态类型。</p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>is_convertible的静态常量成员value用于获取返回的布尔值，is_convertible&lt;From, To&gt;::value取值如下：</p><ul><li>true：From类型的对象可以隐式转换为To类型。</li><li>false：From类型的对象不能隐式转换为To类型。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class Base {};</span></span>
<span class="line"><span>class Derived : public Base {};</span></span>
<span class="line"><span>class Unrelated {};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 检查 int 是否可以隐式转换为 double</span></span>
<span class="line"><span>AscendC::PRINTF(&quot;Is int convertible to double? %d\\n&quot;, AscendC::Std::is_convertible&lt;int, double&gt;::value);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 检查 double 是否可以隐式转换为 int</span></span>
<span class="line"><span>AscendC::PRINTF(&quot;Is double convertible to int? %d\\n&quot;, AscendC::Std::is_convertible&lt;double, int&gt;::value);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 检查 Derived 是否可以转换为 Base</span></span>
<span class="line"><span>AscendC::PRINTF(&quot;Is Derived callable with Base? %d\\n&quot;, AscendC::Std::is_convertible&lt;Derived, Base&gt;::value);</span></span>
<span class="line"><span>// 检查 Base 是否可以转换为 Derived</span></span>
<span class="line"><span>AscendC::PRINTF(&quot;Is Base callable with Derived? %d\\n&quot;, AscendC::Std::is_convertible&lt;Base, Derived&gt;::value);</span></span>
<span class="line"><span>// 检查 Derived 是否可以转换为 Unrelated</span></span>
<span class="line"><span>AscendC::PRINTF(&quot;Is Derived callable with Unrelated? %d\\n&quot;, AscendC::Std::is_convertible&lt;Derived, Unrelated&gt;::value);</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 执行结果：</span></span>
<span class="line"><span>Is int convertible to double? 1</span></span>
<span class="line"><span>Is double convertible to int? 1</span></span>
<span class="line"><span>Is Derived callable with Base? 1</span></span>
<span class="line"><span>Is Base callable with Derived? 0</span></span>
<span class="line"><span>Is Derived callable with Unrelated? 0</span></span></code></pre></div>`,18)])])}const u=e(l,[["render",i]]);export{b as __pageData,u as default};
